release-hold:
set -e
sudo -n test -d /var/lib/rosy/models || sudo -n install -d -o root -g rosy-camera -m 0750 /var/lib/rosy/models
sudo -n sh -c ': >> /var/lib/rosy/models/.lock; chown root:rosy-camera /var/lib/rosy/models/.lock; chmod 0640 /var/lib/rosy/models/.lock'
sudo -n flock -E 75 -w 30 /var/lib/rosy/models/.lock sh -c 'set +e
(
set -e
cur=$(cat /var/lib/rosy/models/shadow 2>/dev/null || true)
test -e /var/lib/rosy/models/history.jsonl || install -o root -g rosy-camera -m 0640 /dev/null /var/lib/rosy/models/history.jsonl
(: >> /var/lib/rosy/models/history.jsonl) 2>/dev/null || { echo '"'"'history.jsonl is not appendable; nothing changed'"'"' >&2; exit 3; }
rm -f /var/lib/rosy/models/hold
printf '"'"'{"ts":"%s","action":%s,"revision":"%s","previous":"%s","operator":%s,"host_of_operator":%s,"tool_commit":%s}\n'"'"' "$(date -u +%Y-%m-%dT%H:%M:%SZ)" '"'"'"release-hold"'"'"' "$(printf %s "${cur##*/}" | tr -cd '"'"'A-Za-z0-9._-'"'"')" "$(printf %s "${cur##*/}" | tr -cd '"'"'A-Za-z0-9._-'"'"')" '"'"'"ana"'"'"' '"'"'"op-pc"'"'"' '"'"'"cccccccccccccccccccccccccccccccccccccccc"'"'"' | tee -a /var/lib/rosy/models/history.jsonl >/dev/null || { echo '"'"'pointer changed, history not written'"'"' >&2; exit 3; }
sync -f /var/lib/rosy/models/history.jsonl || { echo '"'"'pointer changed; history durability unknown'"'"' >&2; exit 3; }
)
rc=$?
case $rc in 75|76) rc=1;; esac
exit $rc' || { rc=$?;
  [ $rc -ne 75 ] || echo 'models lock /var/lib/rosy/models/.lock busy for 30 s: another push or rollback is running; retry later' >&2;
  exit $rc; }

rollback:
set -e
sudo -n test -d /var/lib/rosy/models || sudo -n install -d -o root -g rosy-camera -m 0750 /var/lib/rosy/models
sudo -n sh -c ': >> /var/lib/rosy/models/.lock; chown root:rosy-camera /var/lib/rosy/models/.lock; chmod 0640 /var/lib/rosy/models/.lock'
sudo -n flock -E 75 -w 30 /var/lib/rosy/models/.lock sh -c 'set +e
(
set -e
test -f /var/lib/rosy/models/shadow.previous || { echo '"'"'no shadow.previous to roll back to'"'"' >&2; exit 1; }
cur=$(cat /var/lib/rosy/models/shadow 2>/dev/null || true)
new=$(cat /var/lib/rosy/models/shadow.previous)
test -e /var/lib/rosy/models/history.jsonl || install -o root -g rosy-camera -m 0640 /dev/null /var/lib/rosy/models/history.jsonl
(: >> /var/lib/rosy/models/history.jsonl) 2>/dev/null || { echo '"'"'history.jsonl is not appendable; nothing changed'"'"' >&2; exit 3; }
install -o root -g rosy-camera -m 0640 /dev/null /var/lib/rosy/models/hold.tmp
printf '"'"'{"by":%s,"host":%s,"ts":"%s","action":%s,"revision":"%s","reason":%s}\n'"'"' '"'"'"ana"'"'"' '"'"'"op-pc"'"'"' "$(date -u +%Y-%m-%dT%H:%M:%SZ)" '"'"'"rollback"'"'"' "$(printf %s "${new##*/}" | tr -cd '"'"'A-Za-z0-9._-'"'"')" '"'"'"manual rollback"'"'"' > /var/lib/rosy/models/hold.tmp
mv /var/lib/rosy/models/hold.tmp /var/lib/rosy/models/hold
mv /var/lib/rosy/models/shadow.previous /var/lib/rosy/models/shadow
sync
printf '"'"'{"ts":"%s","action":%s,"revision":"%s","previous":"%s","operator":%s,"host_of_operator":%s,"tool_commit":%s}\n'"'"' "$(date -u +%Y-%m-%dT%H:%M:%SZ)" '"'"'"rollback"'"'"' "$(printf %s "${new##*/}" | tr -cd '"'"'A-Za-z0-9._-'"'"')" "$(printf %s "${cur##*/}" | tr -cd '"'"'A-Za-z0-9._-'"'"')" '"'"'"ana"'"'"' '"'"'"op-pc"'"'"' '"'"'"cccccccccccccccccccccccccccccccccccccccc"'"'"' | tee -a /var/lib/rosy/models/history.jsonl >/dev/null || { echo '"'"'pointer changed, history not written'"'"' >&2; exit 3; }
sync -f /var/lib/rosy/models/history.jsonl || { echo '"'"'pointer changed; history durability unknown'"'"' >&2; exit 3; }
)
rc=$?
case $rc in 75|76) rc=1;; esac
exit $rc' || { rc=$?;
  [ $rc -ne 75 ] || echo 'models lock /var/lib/rosy/models/.lock busy for 30 s: another push or rollback is running; retry later' >&2;
  exit $rc; }

